#' Plot Semivariance and Fitted Variogram Curve
#'
#' @description Plots the empirical semivariance scatter points, and optionally overlays 
#' the theoretical variogram curve if a fitted model is provided.
#'
#' @param v Data frame containing empirical semivariance calculation results (must contain \code{dist} and \code{gamma} columns).
#' @param m Object, the variogram fit model generated by the gstat package (defaults to \code{NULL}).
#'
#' @return A \code{ggplot2} semivariance plot object.
#' 
#' @export
vgm_plot <- function(v, m = NULL) {
  p <- ggplot() + 
    geom_point(data = v, aes(x = dist, y = gamma))
  
  # If a theoretical model is provided, compute and overlay fitted prediction lines
  if(!is.null(m)){
    preds <- variogramLine(object = m, maxdist = max(v$dist))
    p <- p + geom_line(data = preds, aes(x = dist, y = gamma))
  }
  
  return(p)
}